/bin/bash -lc "cat > src/util/checkoutRequest.mjs <<'EOF'
/**
 * Builds the checkout request the storefront POSTs to "'`cart/<cartCode>/checkout`.
 *
 * Body field names follow the backend'"'s order request classes:
 * - "'`PersistableAnonymousOrder`: quoteId, currency, termsAccepted, orderNote, payment
 * - `PersistablePayment`: paymentType, transactionType, cardToken, processor, amount
 */
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments,
}) {
  return {
    method: "POST",
    path: `cart/${cartCode}/checkout`,
    body: {
      quoteId: shippingOptionId,
      currency,
      termsAccepted: agreedToTerms,
      orderNote: comments,
      payment: {
        paymentType: "CREDITCARD",
        transactionType: "CAPTURE",
        processor: paymentModule,
        cardToken: paymentToken,
        amount,
      },
    },
  };
}
EOF
node --input-type=module -e "import('"'./src/util/checkoutRequest.mjs').then(m => console.log(JSON.stringify(m.buildCheckoutRequest({cartCode:'C1', shippingOptionId:7, currency:'USD', paymentToken:'tok_x', paymentModule:'stripe', amount:'19.99', agreedToTerms:true, comments:'hi'}), null, 2)))\""
